  1→import express, { Request, Response } from "express";
  2→import { query, AgentDefinition, SettingSource, HookCallbackMatcher } from "@anthropic-ai/claude-agent-sdk";
  3→import { Langfuse } from "langfuse";
  4→import { mkdirSync, writeFileSync, existsSync, readdirSync } from "fs";
  5→import { homedir } from "os";
  6→import { join } from "path";
  7→import type { QueryRequest, HealthResponse, AgentDefinitionPayload } from "./types.js";
  8→
  9→// Claude CLI requires certain directories/files under ~/.claude to exist.
 10→// The container uses a tmpfs mount at ~/.claude which starts empty, so we
 11→// create the expected structure at startup.
 12→const claudeDir = join(homedir(), ".claude");
 13→for (const sub of ["debug", "projects"]) {
 14→  const dir = join(claudeDir, sub);
 15→  if (!existsSync(dir)) {
 16→    mkdirSync(dir, { recursive: true });
 17→  }
 18→}
 19→const settingsFile = join(claudeDir, "remote-settings.json");
 20→if (!existsSync(settingsFile)) {
 21→  writeFileSync(settingsFile, "{}");
 22→}
 23→
 24→const SKILLS_DIR = join(process.cwd(), ".claude", "skills");
 25→
 26→function discoverSkills(): Set<string> {
 27→  if (!existsSync(SKILLS_DIR)) return new Set();
 28→  return new Set(
 29→    readdirSync(SKILLS_DIR, { withFileTypes: true })
 30→      .filter((d) => d.isDirectory() && existsSync(join(SKILLS_DIR, d.name, "SKILL.md")))
 31→      .map((d) => d.name)
 32→  );
 33→}
 34→
 35→// Log initial skills at startup
 36→console.log(`[sidecar] Initial skills: ${[...discoverSkills()].join(", ") || "(none)"}`);
 37→
 38→const skillAllowlistHook: HookCallbackMatcher = {
 39→  matcher: "Skill",
 40→  hooks: [
 41→    async (input) => {
 42→      const currentSkills = discoverSkills();
 43→      const toolInput = (input as Record<string, unknown>).tool_input as Record<string, unknown> | undefined;
 44→      const skillName = toolInput?.skill as string | undefined;
 45→      if (skillName && !currentSkills.has(skillName)) {
 46→        return {
 47→          hookSpecificOutput: {
 48→            hookEventName: "PreToolUse" as const,
 49→            permissionDecision: "deny" as const,
 50→            permissionDecisionReason: `Skill "${skillName}" is not in the allowlist.`,
 51→          },
 52→        };
 53→      }
 54→      return {};
 55→    },
 56→  ],
 57→};
 58→
 59→// Initialize Langfuse if credentials are available (reads from env vars
 60→// LANGFUSE_PUBLIC_KEY, LANGFUSE_SECRET_KEY, LANGFUSE_BASE_URL automatically)
 61→let langfuse: Langfuse | null = null;
 62→if (process.env.LANGFUSE_PUBLIC_KEY && process.env.LANGFUSE_SECRET_KEY) {
 63→  langfuse = new Langfuse();
 64→  console.log("[sidecar] Langfuse tracing enabled");
 65→}
 66→
 67→const app = express();
 68→app.use(express.json({ limit: "10mb" }));
 69→
 70→const PORT = parseInt(process.env.PORT || "3000", 10);
 71→
 72→// Per-request abort tracking — avoids a global variable whose cleanup in one
 73→// request's `finally` block can clobber a concurrently-started request.
 74→let nextRequestId = 0;
 75→const activeAborts = new Map<number, AbortController>();
 76→
 77→// How long (ms) to wait for the SDK iterator to yield a message before
 78→// aborting.  Resets on every message so active multi-turn queries are not
 79→// interrupted.  Covers cases where the CLI subprocess hangs on startup
 80→// (e.g. broken session resume, unreachable MCP server).
 81→const SDK_IDLE_TIMEOUT_MS = parseInt(process.env.SDK_IDLE_TIMEOUT_MS || "120000", 10);
 82→
 83→// Timeout (ms) for pre-flight reachability checks against MCP / API URLs.
 84→const PREFLIGHT_TIMEOUT_MS = 10_000; // 10 seconds
 85→
 86→app.get("/health", (_req: Request, res: Response) => {
 87→  const response: HealthResponse = { status: "ok" };
 88→  res.json(response);
 89→});
 90→
 91→app.post("/query", async (req: Request, res: Response) => {
 92→  const body = req.body as QueryRequest;
 93→
 94→  if (!body.message || !body.system_prompt) {
 95→    res.status(400).json({ error: "message and system_prompt are required" });
 96→    return;
 97→  }
 98→
 99→  // Set up SSE headers
100→  res.setHeader("Content-Type", "text/event-stream");
101→  res.setHeader("Cache-Control", "no-cache");
102→  res.setHeader("Connection", "keep-alive");
103→  res.setHeader("X-Accel-Buffering", "no");
104→  res.flushHeaders();
105→
106→  const abortController = new AbortController();
107→  const requestId = nextRequestId++;
108→  activeAborts.set(requestId, abortController);
109→
110→  // Merge per-request env overrides (e.g. Bifrost gateway URLs) with process env
111→  const sdkEnv: Record<string, string> = {};
112→  for (const [k, v] of Object.entries(process.env)) {
113→    if (v !== undefined) sdkEnv[k] = v;
114→  }
115→  if (body.env) {
116→    Object.assign(sdkEnv, body.env);
117→  }
118→  // Scrub Langfuse credentials so the agent subprocess cannot read them from
119→  // the inherited environment — matches backend subprocess behaviour.
120→  // The sidecar's own Langfuse client already holds the credentials internally.
121→  sdkEnv["LANGFUSE_PUBLIC_KEY"] = "";
122→  sdkEnv["LANGFUSE_SECRET_KEY"] = "";
123→
124→  let responseEnded = false;
125→
126→  // Detect client disconnect
127→  res.on("close", () => {
128→    if (!responseEnded) {
129→      abortController.abort();
130→    }
131→  });
132→
133→  // --- Langfuse tracing setup ---
134→  // Mirror the backend's session ID handling:
135→  //   - langfuse_session_id (from frontend for edit/delete) takes priority
136→  //   - session_id (CLI session from previous turn) as fallback
137→  const modelName = body.model || process.env.ORCHESTRATOR_MODEL || "claude-sonnet-4-6";
138→  const traceMessage = body.original_message || body.message;
139→  const traceInput: Record<string, unknown> = {
140→    message: traceMessage.substring(0, 500),
141→  };
142→  if (body.conversation_history && body.conversation_history.length > 0) {
143→    traceInput.conversation_history = body.conversation_history;
144→  }
145→  const trace = langfuse?.trace({
146→    name: "agent-chat",
147→    sessionId: body.langfuse_session_id || body.session_id || undefined,
148→    input: traceInput,
149→    metadata: { model: modelName, mode: "container" },
150→  });
151→
152→  // Per-turn usage tracking from stream events
153→  let currentGenUsage: { input?: number; output?: number } = {};
154→  // Accumulated messages for generation input context
155→  const accumulatedMessages: Array<{ role: string; content: unknown }> = [
156→    { role: "user", content: body.message },
157→  ];
158→
159→  // Collect stderr from the CLI subprocess for debugging
160→  const stderrLines: string[] = [];
161→
162→  // Declared here so `finally` can clear it even if `try` throws early
163→  let idleTimer: ReturnType<typeof setTimeout> | null = null;
164→
165→  try {
166→    // --- Pre-flight reachability checks ---
167→    // The CLI subprocess will hang silently if it can't reach the MCP SSE
168→    // server or the Bifrost LLM gateway.  Test connectivity first so we can
169→    // fail fast with a useful error message.
170→    const apiBase = sdkEnv["ANTHROPIC_BASE_URL"] || "";
171→    console.log(
172→      `[sidecar] reqId=${requestId} mcp_url=${body.mcp_server_url || "(none)"} api_base=${apiBase} session_id=${body.session_id || "(none)"}`
173→    );
174→
175→    if (body.mcp_server_url) {
176→      try {
177→        const mcpResp = await fetch(body.mcp_server_url, {
178→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
179→        });
180→        // SSE endpoints normally return 200 with text/event-stream; any
181→        // non-error status is fine — we just need to know the host is up.
182→        mcpResp.body?.cancel(); // don't consume the stream
183→        console.log(`[sidecar] MCP reachability OK (status=${mcpResp.status})`);
184→      } catch (e: unknown) {
185→        const reason = e instanceof Error ? e.message : String(e);
186→        throw new Error(
187→          `MCP server unreachable at ${body.mcp_server_url}: ${reason}. ` +
188→          `Check that BACKEND_BASE_URL is reachable from inside the container.`
189→        );
190→      }
191→    }
192→
193→    if (apiBase) {
194→      try {
195→        // Just a quick TCP-level check — Bifrost will return 4xx without
196→        // a real API key but that still proves reachability.
197→        const apiResp = await fetch(`${apiBase}/v1/models`, {
198→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
199→        });
200→        apiResp.body?.cancel();
201→        console.log(`[sidecar] Bifrost LLM gateway reachability OK (status=${apiResp.status})`);
202→      } catch (e: unknown) {
203→        const reason = e instanceof Error ? e.message : String(e);
204→        throw new Error(
205→          `Bifrost LLM gateway unreachable at ${apiBase}: ${reason}. ` +
206→          `Check that BIFROST_BASE_URL is reachable from inside the container.`
207→        );
208→      }
209→    }
210→
211→    // Convert agents payload from the backend into SDK AgentDefinition objects.
212→    // The SDK only accepts 'sonnet' | 'opus' | 'haiku' | 'inherit' for model.
213→    // Arbitrary strings (e.g. "openai/gpt-5.2") are silently rejected, causing
214→    // the agent to not be registered.  Validate and fall back to "inherit".
215→    const VALID_AGENT_MODELS = new Set(["sonnet", "opus", "haiku", "inherit"]);
216→    let sdkAgents: Record<string, AgentDefinition> | undefined;
217→    if (body.agents) {
218→      sdkAgents = {};
219→      for (const [name, def] of Object.entries(body.agents)) {
220→        const model = def.model && VALID_AGENT_MODELS.has(def.model)
221→          ? (def.model as AgentDefinition["model"])
222→          : "inherit";
223→        sdkAgents[name] = {
224→          description: def.description,
225→          prompt: def.prompt,
226→          ...(def.tools ? { tools: def.tools } : {}),
227→          model,
228→        };
229→      }
230→    }
231→
232→    // Append skill restriction so the model doesn't list or suggest
233→    // built-in skills that the PreToolUse hook would block anyway.
234→    // The CLI binary injects its own system reminder listing ALL skills
235→    // (including built-ins like "simplify"), so we must explicitly tell
236→    // the model to ignore any skills not in our allowlist.
237→    const currentSkills = discoverSkills();
238→    const allowedList = [...currentSkills].join(", ");
239→    const skillRestriction = currentSkills.size > 0
240→      ? `\n\nCRITICAL SKILL RESTRICTION: Your ONLY available skills are: ${allowedList}. You may see other skills (like "simplify") listed in system reminders — those are NOT available to you and MUST be ignored. When asked about available skills, list ONLY: ${allowedList}. Never mention, suggest, or attempt to invoke any skill not in this list.`
241→      : "\n\nCRITICAL SKILL RESTRICTION: You have NO skills available. You may see skills listed in system reminders — those are NOT available to you and MUST be ignored. Never mention, suggest, or attempt to invoke any skills.";
242→
243→    const skillInstruction = body.skills?.length
244→      ? `\n\nIMPORTANT: The user has invoked the following skill(s): ${body.skills.map(s => `"/${s}"`).join(", ")}. You MUST use the Skill tool to invoke each skill (${body.skills.map(s => `"${s}"`).join(", ")}) before doing anything else.`
245→      : "";
246→
247→    // Common SDK options (without resume/prompt — those vary on retry)
248→    const baseOptions = {
249→      model: modelName,
250→      systemPrompt: body.system_prompt + skillInstruction + skillRestriction,
251→      allowedTools: ["Skill", "Task", "mcp__duckdb-data-agent__execute_sql", "mcp__duckdb-data-agent__ask_user_question", "mcp__duckdb-data-agent__render_chart", "mcp__duckdb-data-agent__create_skill"] as string[],
252→      settingSources: ["project"] as SettingSource[],
253→      plugins: [],
254→      hooks: { PreToolUse: [skillAllowlistHook] },
255→      permissionMode: "bypassPermissions" as const,
256→      allowDangerouslySkipPermissions: true,
257→      maxTurns: 20,
258→      includePartialMessages: true,
259→      abortController,
260→      env: sdkEnv,
261→      stderr: (line: string) => {
262→        stderrLines.push(line);
263→        console.error(`[sidecar:cli] ${line}`);
264→      },
265→      ...(sdkAgents ? { agents: sdkAgents } : {}),
266→      ...(body.mcp_server_url
267→        ? {
268→            mcpServers: {
269→              "duckdb-data-agent": {
270→                type: "sse" as const,
271→                url: body.mcp_server_url,
272→              },
273→            },
274→          }
275→        : {}),
276→    };
277→
278→    // Resume fallback: try with resume first. If the SDK yields a "result"
279→    // message with "No conversation found" (container was recreated and lost
280→    // the session), suppress that error and retry without resume, prepending
281→    // conversation history so the model has context.
282→    let currentPrompt = body.message;
283→    let useResume = !!body.session_id;
284→    let retried = false;
285→
286→    queryLoop: for (let attempt = 0; attempt < 2; attempt++) {
287→      const sdkQuery = query({
288→        prompt: currentPrompt,
289→        options: {
290→          ...baseOptions,
291→          ...(useResume ? { resume: body.session_id } : {}),
292→        },
293→      });
294→
295→      console.log(
296→        `[sidecar] SDK query started model=${modelName} reqId=${requestId} attempt=${attempt} resume=${useResume}`
297→      );
298→
299→      idleTimer = setTimeout(() => {
300→        console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
301→        abortController.abort();
302→      }, SDK_IDLE_TIMEOUT_MS);
303→
304→      let resumeFailedNeedsRetry = false;
305→
306→      try {
307→        for await (const message of sdkQuery) {
308→          // Reset idle timer on every message
309→          if (idleTimer) { clearTimeout(idleTimer); }
310→          idleTimer = setTimeout(() => {
311→            console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
312→            abortController.abort();
313→          }, SDK_IDLE_TIMEOUT_MS);
314→
315→          if (responseEnded) break queryLoop;
316→
317→          // Intercept "No conversation found" result before forwarding
318→          if (useResume && !retried) {
319→            const msg = message as Record<string, unknown>;
320→            if (msg.type === "result" && msg.is_error) {
321→              const resultText = String(msg.result || "");
322→              const errors = ((msg.errors as string[]) || []).join(" ");
323→              if ((resultText + " " + errors).includes("No conversation found")
324→                  && body.conversation_history && body.conversation_history.length > 0) {
325→                console.log(`[sidecar] Resume failed ("No conversation found"), will retry with history reqId=${requestId}`);
326→                resumeFailedNeedsRetry = true;
327→                break; // Don't forward this error to the client
328→              }
329→            }
330→          }
331→
332→          // Forward each SDK message as an SSE data line
333→          res.write(`data: ${JSON.stringify(message)}\n\n`);
334→
335→          // --- Create Langfuse observations from SDK messages ---
336→          if (!trace) continue;
337→          const msg = message as Record<string, unknown>;
338→
339→          if (msg.type === "stream_event") {
340→            const event = (msg.event as Record<string, unknown>) || {};
341→            const eventType = event.type as string;
342→            if (eventType === "message_start") {
343→              const msgData = (event.message as Record<string, unknown>) || {};
344→              const usage = (msgData.usage as Record<string, number>) || {};
345→              currentGenUsage = { input: usage.input_tokens || 0 };
346→            } else if (eventType === "message_delta") {
347→              const usage = (event.usage as Record<string, number>) || {};
348→              currentGenUsage.output = usage.output_tokens || 0;
349→            }
350→          } else if (msg.type === "assistant") {
351→            const msgObj = (msg.message as Record<string, unknown>) || {};
352→            const content = msgObj.content as unknown[];
353→            const usage =
354→              currentGenUsage.input !== undefined
355→                ? {
356→                    input: currentGenUsage.input || 0,
357→                    output: currentGenUsage.output || 0,
358→                    total: (currentGenUsage.input || 0) + (currentGenUsage.output || 0),
359→                    unit: "TOKENS" as const,
360→                  }
361→                : undefined;
362→            const gen = trace.generation({
363→              name: "claude.assistant.turn",
364→              model: (msgObj.model as string) || modelName,
365→              input: { messages: accumulatedMessages.slice(-6) },
366→              output: { content, role: "assistant" },
367→              usage,
368→            });
369→            gen.end();
370→            currentGenUsage = {};
371→            accumulatedMessages.push({ role: "assistant", content });
372→          } else if (msg.type === "user") {
373→            const msgObj = (msg.message as Record<string, unknown>) || {};
374→            accumulatedMessages.push({ role: "user", content: msgObj.content });
375→          } else if (msg.type === "result") {
376→            const actualSessionId = (msg.session_id as string | undefined) || body.session_id;
377→            const traceSessionId = body.langfuse_session_id || actualSessionId;
378→            trace.update({
379→              ...(traceSessionId ? { sessionId: traceSessionId } : {}),
380→              output: { session_id: actualSessionId },
381→            });
382→          } else if (msg.type === "system") {
383→            const sessionId = msg.session_id as string | undefined;
384→            if (sessionId && !body.langfuse_session_id) {
385→              trace.update({ sessionId });
386→            }
387→          }
388→        } // end for-await
389→      } catch (innerErr: unknown) {
390→        // If we're retrying due to resume failure, swallow the cleanup error
391→        // (e.g., "Claude Code process exited with code 1" after session not found)
392→        if (resumeFailedNeedsRetry) {
393→          console.log(`[sidecar] Swallowing post-resume error during retry: ${innerErr instanceof Error ? innerErr.message : String(innerErr)}`);
394→        } else {
395→          throw innerErr;
396→        }
397→      }
398→
399→      if (resumeFailedNeedsRetry && !retried) {
400→        retried = true;
401→        useResume = false;
402→        let messageWithHistory = "Previous conversation (for context):\n";
403→        for (const entry of body.conversation_history!) {
404→          const role = (entry.role || "user").charAt(0).toUpperCase() + (entry.role || "user").slice(1);
405→          messageWithHistory += `\n${role}: ${entry.content}\n`;
406→        }
407→        messageWithHistory += `\n---\n\nMy new message:\n${body.message}`;
408→        currentPrompt = messageWithHistory;
409→        stderrLines.length = 0;
410→        if (idleTimer) { clearTimeout(idleTimer); idleTimer = null; }
411→        continue; // retry the queryLoop
412→      }
413→
414→      break; // success or non-retryable error — exit queryLoop
415→    } // end queryLoop
416→  } catch (err: unknown) {
417→    let errMsg = err instanceof Error ? err.message : String(err);
418→    // Append CLI stderr for context when the process crashes
419→    if (stderrLines.length > 0) {
420→      errMsg += ` | CLI stderr: ${stderrLines.slice(-5).join(" ")}`;
421→    }
422→    // Don't log abort errors — they are expected on client disconnect
423→    if (!(err instanceof Error && err.name === "AbortError")) {
424→      console.error(`[sidecar] SDK error: ${errMsg}`);
425→      if (!responseEnded) {
426→        res.write(
427→          `data: ${JSON.stringify({ type: "error", message: errMsg })}\n\n`
428→        );
429→      }
430→      if (trace) {
431→        trace.update({ output: { error: errMsg } });
432→      }
433→    }
434→  } finally {
435→    if (idleTimer) { clearTimeout(idleTimer); }
436→    activeAborts.delete(requestId);
437→    responseEnded = true;
438→    res.end();
439→    // Flush Langfuse events before the response is fully closed
440→    if (langfuse) {
441→      await langfuse.flushAsync().catch(() => {});
442→    }
443→    console.log(`[sidecar] SSE stream ended reqId=${requestId}`);
444→  }
445→});
446→
447→app.post("/stop", (_req: Request, res: Response) => {
448→  if (activeAborts.size > 0) {
449→    for (const [id, controller] of activeAborts) {
450→      controller.abort();
451→      activeAborts.delete(id);
452→    }
453→    res.json({ status: "stopped" });
454→  } else {
455→    res.json({ status: "no_active_session" });
456→  }
457→});
458→
459→app.listen(PORT, "0.0.0.0", () => {
460→  console.log(`Sidecar agent server listening on port ${PORT}`);
461→});
