177→function handleSSEEvent(
178→  eventType: string,
179→  data: Record<string, unknown>,
180→  callbacks: AgentCallbacks,
181→) {
182→  switch (eventType) {
183→    case 'thinking':
184→    case 'answer':
185→      callbacks.onTextChunk(data.text as string);
186→      break;
187→    case 'thinking_done':
188→      callbacks.onThinkingDone();
189→      break;
190→    case 'tool_call':
191→      callbacks.onToolCall({
192→        toolCallId: (data.id as string) ?? '',
193→        toolName: (data.name as string) ?? undefined,
194→        sql: (data.sql as string) ?? '',
195→        command: (data.command as string) ?? undefined,
196→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
197→        columns: [],
198→        rows: [],
199→        rowCount: 0,
200→      });
201→      break;
202→    case 'tool_result': {
203→      const result: ToolCallResult = {
204→        toolCallId: (data.id as string) ?? '',
205→        toolName: (data.name as string) ?? undefined,
206→        sql: (data.sql as string) ?? '',
207→        columns: (data.columns as string[]) ?? [],
208→        rows: (data.rows as Record<string, unknown>[]) ?? [],
209→        rowCount: (data.rowCount as number) ?? 0,
210→        error: (data.error as string) ?? undefined,
211→        output: (data.output as string) ?? undefined,
212→        rawContent: (data.content as string) ?? undefined,
213→        chart_spec: (data.chart_spec as { data: unknown[]; layout?: Record<string, unknown> }) ?? undefined,
214→      };
215→      callbacks.onToolResult(result);
216→      break;
217→    }
218→    case 'subagent_start':
219→      callbacks.onSubagentStart?.({
220→        id: data.id as string,
221→        name: data.name as string,
222→        prompt: (data.prompt as string) ?? '',
223→      });
224→      break;
225→    case 'subagent_end': {
226→      type ChartSpec = { data: unknown[]; layout?: Record<string, unknown>; frames?: unknown[] };
227→      // Backend sends chart_specs (array) for multi-chart support.
228→      // Fall back to legacy chart_spec (single object) for backwards compat.
229→      const rawSpecs = data.chart_specs as ChartSpec[] | undefined;
230→      const legacySpec = data.chart_spec as ChartSpec | undefined;
231→      const chartSpecs: ChartSpec[] = rawSpecs ?? (legacySpec ? [legacySpec] : []);
232→
233→      if (chartSpecs.length > 0) {
234→        // Emit one callback per chart so each gets its own segment
235→        for (const spec of chartSpecs) {
236→          callbacks.onSubagentEnd?.({
237→            id: data.id as string,
238→            name: data.name as string,
239→            chart_spec: spec,
240→          });
241→        }
242→        // Emit text result separately (if any) so it doesn't get lost
243→        if (data.result) {
244→          callbacks.onSubagentEnd?.({
245→            id: data.id as string,
246→            name: data.name as string,
247→            result: data.result as string,
248→          });
249→        }
250→      } else {
251→        callbacks.onSubagentEnd?.({
252→          id: data.id as string,
253→          name: data.name as string,
254→          result: (data.result as string) ?? undefined,
255→          sql_results: (data.sql_results as Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>) ?? undefined,
256→        });
257→      }
258→      break;
259→    }
260→    case 'user_question': {
261→      // Normalize options: the agent may send plain strings or {label, description} objects
262→      const rawOptions = (data.options as unknown[]) ?? [];
263→      const normalizedOptions: UserQuestionOption[] = (Array.isArray(rawOptions) ? rawOptions : []).map(
264→        (opt: unknown) => {
265→          if (typeof opt === 'string') return { label: opt };
266→          if (typeof opt === 'object' && opt !== null && 'label' in opt) return opt as UserQuestionOption;
267→          return { label: String(opt) };
268→        }
269→      );
270→      callbacks.onUserQuestion?.({
271→        questionId: data.question_id as string,
272→        question: data.question as string,
273→        options: normalizedOptions,
274→        multiSelect: (data.multi_select as boolean) ?? false,
275→      });
276→      break;
277→    }
278→    case 'done':
279→      callbacks.onDone((data.session_id as string) ?? null);
280→      break;
281→    case 'error':
282→      callbacks.onError((data.message as string) ?? 'Unknown error');
283→      break;
284→  }
285→}
